1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	type ItemTypeSpec = {
47	  basePremium: number;
48	  insuranceValue: number;
49	};
50	
51	const ITEM_CATALOGUE: Record<string, ItemTypeSpec> = {
52	  sword: { basePremium: 100, insuranceValue: 1000 },
53	  amulet: { basePremium: 60, insuranceValue: 600 },
54	  staff: { basePremium: 80, insuranceValue: 800 },
55	  potion: { basePremium: 40, insuranceValue: 400 },
56	  rune: { basePremium: 25, insuranceValue: 250 },
57	  moonstone: { basePremium: 25, insuranceValue: 250 },
58	};
59	
60	const basePremiumOf = (item: Item): number =>
61	  ITEM_CATALOGUE[item.type].basePremium;
62	
63	const insuranceValueOf = (item: Item): number =>
64	  ITEM_CATALOGUE[item.type].insuranceValue;
65	
66	const BLOCK_SIZE = 3;
67	const BLOCK_BASE_PREMIUM = 60;
68	
69	const itemsGroupedByType = (items: Item[]): Item[][] => [
70	  ...items
71	    .reduce(
72	      (groupsByType, item) =>
73	        groupsByType.set(item.type, [
74	          ...(groupsByType.get(item.type) ?? []),
75	          item,
76	        ]),
77	      new Map<string, Item[]>(),
78	    )
79	    .values(),
80	];
81	
82	const formsABlock = (itemsAlike: Item[]): boolean =>
83	  itemsAlike.length === BLOCK_SIZE;
84	
85	const basePremiumOfItemsAlike = (itemsAlike: Item[]): number =>
86	  formsABlock(itemsAlike)
87	    ? BLOCK_BASE_PREMIUM
88	    : itemsAlike.reduce((total, item) => total + basePremiumOf(item), 0);
89	
90	const totalBasePremiumOf = (items: Item[]): number =>
91	  itemsGroupedByType(items).reduce(
92	    (total, itemsAlike) => total + basePremiumOfItemsAlike(itemsAlike),
93	    0,
94	  );
95	
96	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
97	
98	type Rule<Subject> = {
99	  appliesTo: (subject: Subject) => boolean;
100	  rate: number;
101	};
102	
103	const totalRateOf = <Subject,>(
104	  rules: Rule<Subject>[],
105	  subject: Subject,
106	): number =>
107	  rules.reduce(
108	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
109	    0,
110	  );
111	
112	const CURSE_SURCHARGE_RATE = 0.5;
113	const HIGH_ENCHANTMENT_THRESHOLD = 5;
114	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
115	
116	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
117	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
118	  {
119	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
120	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
121	  },
122	];
123	
124	const itemSurchargeOf = (item: Item): number =>
125	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
126	
127	const totalItemSurchargeOf = (items: Item[]): number =>
128	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
129	
130	const LOYALTY_YEARS_THRESHOLD = 2;
131	const LOYALTY_DISCOUNT_RATE = -0.2;
132	
133	// Levied on every policy, follow-ups included — not only on a customer's first.
134	const INSURANCE_SURCHARGE_RATE = 0.1;
135	
136	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
137	
138	type PolicyContext = {
139	  customer: Customer;
140	  previousContracts: number;
141	};
142	
143	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
144	  {
145	    appliesTo: ({ customer }) =>
146	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
147	    rate: LOYALTY_DISCOUNT_RATE,
148	  },
149	  {
150	    appliesTo: ({ previousContracts }) => previousContracts > 0,
151	    rate: FOLLOW_UP_DISCOUNT_RATE,
152	  },
153	];
154	
155	const totalPolicyModifierRateOf = (policy: PolicyContext): number =>
156	  INSURANCE_SURCHARGE_RATE + totalRateOf(POLICY_MODIFIER_RULES, policy);
157	
158	const quotePremium = (items: Item[], policy: PolicyContext): number => {
159	  const basePremium = totalBasePremiumOf(items);
160	
161	  return roundedUpInMHPCOsFavour(
162	    basePremium +
163	      totalItemSurchargeOf(items) +
164	      basePremium * totalPolicyModifierRateOf(policy) +
165	      PROCESSING_FEE,
166	  );
167	};
168	
169	const DEDUCTIBLE = 100;
170	const CAP_MULTIPLIER = 2;
171	
172	const insuranceSumOf = (items: Item[]): number =>
173	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
174	
175	const payoutCapOf = (items: Item[]): number =>
176	  CAP_MULTIPLIER * insuranceSumOf(items);
177	
178	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
179	const HALVED_REIMBURSEMENT_RATE = 0.5;
180	const FULL_REIMBURSEMENT_RATE = 1;
181	
182	const reimbursementRateFor = (item: Item): number =>
183	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
184	    ? HALVED_REIMBURSEMENT_RATE
185	    : FULL_REIMBURSEMENT_RATE;
186	
187	const payoutForDamage = (damage: Damage, item: Item): number =>
188	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
189	
190	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
191	
192	type ClaimResult = {
193	  payout: number;
194	  remainingCap: number;
195	};
196	
197	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item =>
198	  insuredItems.find((item) => item.type === damage.itemType) as Item;
199	
200	const totalPayoutFor = (damages: Damage[], insuredItems: Item[]): number =>
201	  damages.reduce(
202	    (total, damage) =>
203	      total + payoutForDamage(damage, insuredItemFor(damage, insuredItems)),
204	    0,
205	  );
206	
207	const settleClaim = (incident: Incident, policy: IssuedPolicy): ClaimResult => {
208	  const desiredPayout = totalPayoutFor(incident.damages, policy.insuredItems);
209	  const payout = Math.min(desiredPayout, policy.remainingCap);
210	
211	  return { payout, remainingCap: policy.remainingCap - payout };
212	};
213	
214	// A policy, once quoted, is referred to by later claim steps via its step index.
215	// Its cap depletes as claims are paid out against it.
216	type IssuedPolicy = {
217	  stepIndex: number;
218	  insuredItems: Item[];
219	  remainingCap: number;
220	};
221	
222	// Everything a step needs to know about the steps that came before it.
223	type ScenarioHistory = {
224	  issuedPolicies: IssuedPolicy[];
225	  results: unknown[];
226	};
227	
228	const EMPTY_HISTORY: ScenarioHistory = { issuedPolicies: [], results: [] };
229	
230	const policyAt = (
231	  issuedPolicies: IssuedPolicy[],
232	  policyIndex: number,
233	): IssuedPolicy =>
234	  issuedPolicies.find(
235	    (policy) => policy.stepIndex === policyIndex,
236	  ) as IssuedPolicy;
237	
238	const withStepAppended = (
239	  history: ScenarioHistory,
240	  issuedPolicies: IssuedPolicy[],
241	  result: unknown,
242	): ScenarioHistory => ({
243	  issuedPolicies,
244	  results: [...history.results, result],
245	});
246	
247	const takeQuoteStep = (
248	  step: QuoteStep,
249	  stepIndex: number,
250	  history: ScenarioHistory,
251	  customer: Customer,
252	): ScenarioHistory =>
253	  withStepAppended(
254	    history,
255	    [
256	      ...history.issuedPolicies,
257	      {
258	        stepIndex,
259	        insuredItems: step.items,
260	        remainingCap: payoutCapOf(step.items),
261	      },
262	    ],
263	    {
264	      premium: quotePremium(step.items, {
265	        customer,
266	        previousContracts: history.issuedPolicies.length,
267	      }),
268	    },
269	  );
270	
271	const takeClaimStep = (
272	  step: ClaimStep,
273	  history: ScenarioHistory,
274	): ScenarioHistory => {
275	  const policy = policyAt(history.issuedPolicies, step.policy);
276	  const result = settleClaim(step.incident, policy);
277	
278	  return withStepAppended(
279	    history,
280	    history.issuedPolicies.map((issued) =>
281	      issued === policy
282	        ? { ...issued, remainingCap: result.remainingCap }
283	        : issued,
284	    ),
285	    result,
286	  );
287	};
288	
289	export const runScenario = (scenario: Scenario): ScenarioResult => {
290	  const history = scenario.steps.reduce(
291	    (soFar, step, stepIndex) =>
292	      isQuote(step)
293	        ? takeQuoteStep(step, stepIndex, soFar, scenario.customer)
294	        : takeClaimStep(step, soFar),
295	    EMPTY_HISTORY,
296	  );
297	
298	  return { results: history.results };
299	};
