// A policy, once quoted, is referred to by later claim steps via its step index.
// Its cap depletes as claims are paid out against it.
type IssuedPolicy = {
  stepIndex: number;
  insuredItems: Item[];
  remainingCap: number;
};

// Everything a step needs to know about the steps that came before it.
type ScenarioHistory = {
  issuedPolicies: IssuedPolicy[];
  results: unknown[];
};

const EMPTY_HISTORY: ScenarioHistory = { issuedPolicies: [], results: [] };

const policyAt = (
  issuedPolicies: IssuedPolicy[],
  policyIndex: number,
): IssuedPolicy =>
  issuedPolicies.find(
    (policy) => policy.stepIndex === policyIndex,
  ) as IssuedPolicy;

const withStepAppended = (
  history: ScenarioHistory,
  issuedPolicies: IssuedPolicy[],
  result: unknown,
): ScenarioHistory => ({
  issuedPolicies,
  results: [...history.results, result],
});

const takeQuoteStep = (
  step: QuoteStep,
  stepIndex: number,
  history: ScenarioHistory,
  customer: Customer,
): ScenarioHistory =>
  withStepAppended(
    history,
    [
      ...history.issuedPolicies,
      {
        stepIndex,
        insuredItems: step.items,
        remainingCap: payoutCapOf(step.items),
      },
    ],
    {
      premium: quotePremium(step.items, {
        customer,
        previousContracts: history.issuedPolicies.length,
      }),
    },
  );

const takeClaimStep = (
  step: ClaimStep,
  history: ScenarioHistory,
): ScenarioHistory => {
  const policy = policyAt(history.issuedPolicies, step.policy);
  const result = settleClaim(step.incident, policy);

  return withStepAppended(
    history,
    history.issuedPolicies.map((issued) =>
      issued === policy
        ? { ...issued, remainingCap: result.remainingCap }
        : issued,
    ),
    result,
  );
};

