// A policy, once quoted, is referred to by later claim steps via its step index.
// Its cap depletes as claims are paid out against it.
type IssuedPolicy = {
  insuredItems: Item[];
  remainingCap: number;
};

// Everything a step needs to know about the steps that came before it.
// Policies are keyed by the index of the quote step that issued them, which is
// how a claim step refers to them.
type ScenarioHistory = {
  issuedPolicies: Map<number, IssuedPolicy>;
  results: unknown[];
};

const EMPTY_HISTORY: ScenarioHistory = {
  issuedPolicies: new Map(),
  results: [],
};

const withPolicy = (
  issuedPolicies: Map<number, IssuedPolicy>,
  policyIndex: number,
  policy: IssuedPolicy,
): Map<number, IssuedPolicy> =>
  new Map(issuedPolicies).set(policyIndex, policy);

const withStepAppended = (
  history: ScenarioHistory,
  issuedPolicies: Map<number, IssuedPolicy>,
  result: unknown,
): ScenarioHistory => ({
  issuedPolicies,
  results: [...history.results, result],
});

const takeQuoteStep = (
  step: QuoteStep,
  stepIndex: number,
  history: ScenarioHistory,
  customer: Customer,
): ScenarioHistory =>
  withStepAppended(
    history,
    withPolicy(history.issuedPolicies, stepIndex, {
      insuredItems: step.items,
      remainingCap: payoutCapOf(step.items),
    }),
    {
      premium: quotePremium(step.items, {
        customer,
        previousContracts: history.issuedPolicies.size,
      }),
    },
  );

const takeClaimStep = (
  step: ClaimStep,
  history: ScenarioHistory,
): ScenarioHistory => {
  const policy = history.issuedPolicies.get(step.policy) as IssuedPolicy;
  const { payout, remainingCap } = settleClaim(step.incident, policy);

  return withStepAppended(
    history,
    withPolicy(history.issuedPolicies, step.policy, { ...policy, remainingCap }),
    { payout, remainingCap },
  );
};
